 'class-analytics':id=>{fxLoadCourse(id);navigate('analytics');},
 'generate-task':()=>generate(),
 'task-create':()=>{const count=Number(fxVal('fx-task-count'));fxRequire(Number.isInteger(count)&&count>=1&&count<=5,'题目数量需为 1—5 的整数。');const id=fxVal('fx-task-course');fxRequire(!fxMeta(id).release,'该课程已发布，请先创建修订版本。');const t={id:fxId(),course:id,title:'练习设计 · '+count+' 道候选',type:fxVal('fx-task-type'),level:fxVal('fx-task-level'),request:fxVal('fx-task-request'),count,status:'queued',created:fxNow(),logs:[]};fx.tasks.unshift(t);closeDialog();navigate('tasks');fxRunTask(t);render();},
