 'task-cancel':id=>{const t=fx.tasks.find(t=>t.id===id);fxRequire(['running','queued'].includes(t.status),'任务已结束。');clearTimeout(fxTaskTimers.get(id));t.status='cancelled';t.logs.push({at:fxNow(),text:'用户取消任务'});fxDone('任务已取消，可以显式继续。');},
 'task-interrupt':id=>{const t=fx.tasks.find(t=>t.id===id);clearTimeout(fxTaskTimers.get(id));t.status='failed';t.logs.push({at:fxNow(),text:'演示中断，保留输入，等待手动继续'});fxDone('已演示任务中断，可继续任务。');},
 'task-resume':id=>{const t=fx.tasks.find(t=>t.id===id);fxRequire(['failed','cancelled'].includes(t.status),'仅可继续已取消或中断的任务。');closeDialog();fxRunTask(t);render();},
 'task-course':id=>{openCourse(id,'questions');},
 'candidate-verify':id=>{const c=fx.candidates.find(c=>c.id===id);c.verified=!!(c.question.title&&c.question.explanation);fxPersist();fxCandidates(c.taskId);toast('结构检查完成，仍需教师审核。');},
 'candidate-review':id=>{const c=fx.candidates.find(c=>c.id===id);dialog('审核候选练习',esc(c.question.title),fxSelect('结论','fx-candidate-status',[['approved','通过'],['rejected','退回']], 'approved')+fxField('核对依据','fx-candidate-notes','','textarea')+'<p id="fx-error" class="fx-inline-error"></p>',`${btn('取消','close-dialog')}${fxButton('保存候选审核','candidate-review-save',id,'primary')}`);},
 'candidate-review-save':id=>{const c=fx.candidates.find(c=>c.id===id);fxRequire(fxVal('fx-candidate-notes'),'请填写核对依据。');c.status=fxVal('fx-candidate-status');c.notes=fxVal('fx-candidate-notes');fxPersist();fxCandidates(c.taskId);},
